contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint _value) public payable {
        uint balBefore = address(c).balance;
        require(balBefore >= _value, "insufficient balance for test");

        bool reverted;
        c.sendMoney(target, _value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(
            (reverted && address(c).balance == balBefore) ||
            (!reverted && address(c).balance == balBefore - _value)
        );
    }

    receive() external payable {}
}

